-- ----------------------------
-- Table structure for task_execution_detail
-- ----------------------------
DROP TABLE IF EXISTS `task_execution_detail`;
CREATE TABLE `task_execution_detail`  (
  `id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'id',
  `task_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务id',
  `item_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检测项id',
  `standard_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标准物id',
  `standard_type` enum('zero','measurement') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'measurement' COMMENT '标准物类型：zero-校零物质，measurement-测量物质',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务-检测项-标准物关联表' ROW_FORMAT = DYNAMIC;

